from robot.libraries.BuiltIn import BuiltIn


class ta5g_tshark_filters():
    def __init__(self):
        interfaces = ["f1ap", "ngap", "lte-rrc", "e1ap", "nr-rrc", "x2ap", "s1ap", "iphy", "sctp",
                      "xnap", "nas_5gs", "nas_eps", "eth", "less 1000", "dst port"]
        all_variables_in_scope = BuiltIn().get_variables(no_decoration=True)
        for var_name, var_value in all_variables_in_scope.items():
            if isinstance(var_value, str) and any(interface in var_value for interface in interfaces):
                setattr(self, var_name, var_value)
